ON CONFLICT (email) DO UPDATE SET instrutor_id = EXCLUDED.instrutor_id, ativo = true, senha_hash = EXCLUDED.senha_hash WHERE usuarios.perfil = 'instrutor';
SELECT i.nome, 'igor.batista', '$2b$12$1EbBbJouyYTMTCeHacXW5e5u2PX0Z5VTAQpi73J/xIYJG9Ozq.Pii', 'instrutor', false, true, i.id FROM instrutores i WHERE i.matricula = 'PT-2006'
ON CONFLICT (email) DO UPDATE SET instrutor_id = EXCLUDED.instrutor_id, ativo = true, senha_hash = EXCLUDED.senha_hash WHERE usuarios.perfil = 'instrutor';
SELECT i.nome, 'eduardo.salles', '$2b$12$T3RI7x.gYWdm0CUdNtVKZ.2WQO0ubuqaugatJ1EwN87DXnaOfl2Oa', 'instrutor', false, true, i.id FROM instrutores i WHERE i.matricula = 'PT-2004'
